.version 7.8
.target sm_89
.address_size 64

.visible .entry conv2d_fwd(
    .param .u64 in_ptr,
    .param .u64 wt_ptr,
    .param .u64 bias_ptr,
    .param .u64 out_ptr,
    .param .u32 total_param
)
{
    .reg .pred %p<16>;
    .reg .f32  %f<16>;
    .reg .b32  %r<48>;
    .reg .b64  %rd<24>;

    ld.param.u64 %rd1, [in_ptr];
    ld.param.u64 %rd2, [wt_ptr];
    ld.param.u64 %rd3, [bias_ptr];
    ld.param.u64 %rd4, [out_ptr];
    ld.param.u32 %r0,  [total_param];

    mov.u32 %r1, %ctaid.x;
    mov.u32 %r2, %ntid.x;
    mov.u32 %r3, %tid.x;
    mad.lo.u32 %r4, %r1, %r2, %r3;          // global linear output index

    setp.ge.u32 %p1, %r4, %r0;
    @%p1 bra DONE;

    // Decompose idx -> n (r13), oc (r15), oh (r12), ow (r9)
    mov.u32 %r5, 55;
    mov.u32 %r6, 96;

    div.u32 %r7, %r4, %r5;
    mul.lo.u32 %r8, %r7, %r5;
    sub.u32 %r9, %r4, %r8;                  // ow

    div.u32 %r10, %r7, %r5;
    mul.lo.u32 %r11, %r10, %r5;
    sub.u32 %r12, %r7, %r11;                // oh

    div.u32 %r13, %r10, %r6;
    mul.lo.u32 %r14, %r13, %r6;
    sub.u32 %r15, %r10, %r14;               // oc; n = r13

    mov.f32 %f1, 0f00000000;                // accumulator

    mov.u32 %r16, 0;                        // ic
IC_LOOP:
    setp.ge.u32 %p2, %r16, 3;
    @%p2 bra IC_DONE;

    mov.u32 %r17, 0;                        // kh
KH_LOOP:
    setp.ge.u32 %p3, %r17, 11;
    @%p3 bra KH_DONE;

    // h = oh*4 + kh - 2
    shl.b32 %r18, %r12, 2;
    add.s32 %r18, %r18, %r17;
    sub.s32 %r18, %r18, 2;
    setp.lt.s32 %p4, %r18, 0;
    setp.ge.s32 %p5, %r18, 224;
    or.pred %p6, %p4, %p5;
    @%p6 bra KH_NEXT;

    mov.u32 %r19, 0;                        // kw
KW_LOOP:
    setp.ge.u32 %p7, %r19, 11;
    @%p7 bra KW_DONE;

    // w = ow*4 + kw - 2
    shl.b32 %r20, %r9, 2;
    add.s32 %r20, %r20, %r19;
    sub.s32 %r20, %r20, 2;
    setp.lt.s32 %p8, %r20, 0;
    setp.ge.s32 %p9, %r20, 224;
    or.pred %p10, %p8, %p9;
    @%p10 bra KW_NEXT;

    // input offset = n*150528 + ic*50176 + h*224 + w
    mov.u32 %r21, 150528;
    mul.lo.u32 %r22, %r13, %r21;
    mov.u32 %r23, 50176;
    mad.lo.u32 %r22, %r16, %r23, %r22;
    mov.u32 %r24, 224;
    mad.lo.u32 %r22, %r18, %r24, %r22;
    add.u32 %r22, %r22, %r20;

    mov.u32 %r25, 4;
    mul.wide.u32 %rd5, %r22, %r25;
    add.u64 %rd6, %rd1, %rd5;
    ld.global.f32 %f2, [%rd6];

    // weight offset = oc*363 + ic*121 + kh*11 + kw
    mov.u32 %r26, 363;
    mul.lo.u32 %r27, %r15, %r26;
    mov.u32 %r28, 121;
    mad.lo.u32 %r27, %r16, %r28, %r27;
    mov.u32 %r29, 11;
    mad.lo.u32 %r27, %r17, %r29, %r27;
    add.u32 %r27, %r27, %r19;

    mul.wide.u32 %rd7, %r27, %r25;
    add.u64 %rd8, %rd2, %rd7;
    ld.global.f32 %f3, [%rd8];

    fma.rn.f32 %f1, %f2, %f3, %f1;

KW_NEXT:
    add.u32 %r19, %r19, 1;
    bra KW_LOOP;
KW_DONE:
KH_NEXT:
    add.u32 %r17, %r17, 1;
    bra KH_LOOP;
KH_DONE:
    add.u32 %r16, %r16, 1;
    bra IC_LOOP;
IC_DONE:

    // add bias[oc]
    mul.wide.u32 %rd9, %r15, %r25;
    add.u64 %rd10, %rd3, %rd9;
    ld.global.f32 %f4, [%rd10];
    add.f32 %f1, %f1, %f4;

    // store output
    mul.wide.u32 %rd11, %r4, %r25;
    add.u64 %rd12, %rd4, %rd11;
    st.global.f32 [%rd12], %f1;

DONE:
    ret;
